-- Sanal Türkiye — PostgreSQL + PostGIS şeması (scripts/postgres-aktar.js ile SQLite şemasından üretildi)
CREATE EXTENSION IF NOT EXISTS postgis;
BEGIN;
CREATE TABLE IF NOT EXISTS "afet_destekleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "tutar" DOUBLE PRECISION NOT NULL,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "afet_etkilenen" (
  "afet_id" BIGINT,
  "user_id" BIGINT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("afet_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "afetler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "plaka" TEXT NOT NULL,
  "tur" TEXT NOT NULL,
  "olcum" TEXT,
  "etkilenen" BIGINT NOT NULL DEFAULT 0,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "arkadas_istek_gecmisi" (
  "isteyen" BIGINT NOT NULL,
  "hedef" BIGINT NOT NULL,
  "at" BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS "arkadasliklar" (
  "isteyen" BIGINT,
  "hedef" BIGINT,
  "durum" TEXT NOT NULL DEFAULT 'ISTEK',
  "at" BIGINT NOT NULL,
  "kabul_at" BIGINT,
  PRIMARY KEY ("isteyen", "hedef")
);
CREATE TABLE IF NOT EXISTS "audit_events" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "idempotency_key" TEXT,
  "actor_id" BIGINT,
  "action" TEXT NOT NULL,
  "entity" TEXT,
  "before_json" TEXT,
  "after_json" TEXT,
  "region_id" BIGINT,
  "public" BIGINT NOT NULL DEFAULT 0,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("idempotency_key")
);
CREATE TABLE IF NOT EXISTS "ayarlar" (
  "anahtar" TEXT,
  "deger" TEXT NOT NULL,
  PRIMARY KEY ("anahtar")
);
CREATE TABLE IF NOT EXISTS "balik_atislari" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "plaka" TEXT,
  "tur" TEXT NOT NULL,
  "isirma" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'BEKLIYOR',
  "gun" TEXT NOT NULL,
  "at" BIGINT NOT NULL,
  "takildi_at" BIGINT,
  "agirlik" DOUBLE PRECISION,
  "yem" TEXT,
  "derinlik" TEXT,
  "misina" TEXT,
  "yem_stok" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "banka_kredi" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "ana" DOUBLE PRECISION NOT NULL,
  "faiz" DOUBLE PRECISION NOT NULL,
  "bas" BIGINT NOT NULL,
  "vade" BIGINT NOT NULL,
  "odenen" DOUBLE PRECISION NOT NULL DEFAULT 0,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "kapandi_at" BIGINT,
  "uyarildi" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "banka_vadeli" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "tutar" DOUBLE PRECISION NOT NULL,
  "faiz" DOUBLE PRECISION NOT NULL,
  "bas" BIGINT NOT NULL,
  "vade" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "kapandi_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "bids" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "listing_id" BIGINT NOT NULL,
  "buyer_id" BIGINT NOT NULL,
  "amount" BIGINT NOT NULL,
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "created_at" BIGINT NOT NULL,
  "updated_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "bulmaca_durum" (
  "user_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "seviye" BIGINT NOT NULL DEFAULT 1,
  "yildiz" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id")
);
CREATE TABLE IF NOT EXISTS "bulmaca_gunluk" (
  "user_id" BIGINT,
  "gun" TEXT,
  "odullu" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id", "gun")
);
CREATE TABLE IF NOT EXISTS "bulmaca_oyun" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "seviye" BIGINT NOT NULL,
  "basla_at" BIGINT NOT NULL,
  "bitis_at" BIGINT,
  "durum" TEXT NOT NULL DEFAULT 'OYNUYOR',
  "hamle" BIGINT,
  "yildiz" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "crops" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "crop_type" TEXT NOT NULL,
  "planted_at" BIGINT NOT NULL,
  "ready_at" BIGINT NOT NULL,
  "waterings" BIGINT NOT NULL DEFAULT 0,
  "last_watered_at" BIGINT,
  "status" TEXT NOT NULL DEFAULT 'GROWING',
  "harvested_qty" BIGINT,
  "don" BIGINT NOT NULL DEFAULT 0,
  "yagmur_at" BIGINT,
  "mevsim" TEXT,
  "afet_kati" DOUBLE PRECISION NOT NULL DEFAULT 1,
  "ortu_bitis" BIGINT,
  "gubre" BIGINT NOT NULL DEFAULT 0,
  "ilac" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "deger_endeksi" (
  "tur" TEXT,
  "bolge_id" BIGINT,
  "gun" TEXT,
  "endeks" DOUBLE PRECISION NOT NULL,
  "parsel" BIGINT NOT NULL,
  "islem" BIGINT NOT NULL,
  "hacim" BIGINT NOT NULL,
  PRIMARY KEY ("tur", "bolge_id", "gun")
);
CREATE TABLE IF NOT EXISTS "eposta_tokenlari" (
  "token_hash" TEXT,
  "user_id" BIGINT NOT NULL,
  "tur" TEXT NOT NULL,
  "expires_at" TEXT NOT NULL,
  "kullanildi_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("token_hash")
);
CREATE TABLE IF NOT EXISTS "etkinlik_odulleri" (
  "user_id" BIGINT,
  "etkinlik" TEXT,
  "yil" BIGINT,
  "gorev" BIGINT,
  "odul" DOUBLE PRECISION NOT NULL,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "etkinlik", "yil", "gorev")
);
CREATE TABLE IF NOT EXISTS "fiyat_alarmlari" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "bolge_id" BIGINT NOT NULL,
  "yon" TEXT NOT NULL,
  "hedef" DOUBLE PRECISION NOT NULL,
  "created_at" BIGINT NOT NULL,
  "tetiklendi_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "giden_postalar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "alici" TEXT NOT NULL,
  "konu" TEXT NOT NULL,
  "govde" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  "html" TEXT,
  "durum" TEXT NOT NULL DEFAULT 'GELISTIRME',
  "deneme" BIGINT NOT NULL DEFAULT 0,
  "sonraki" BIGINT,
  "hata" TEXT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "giden_smsler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "telefon" TEXT NOT NULL,
  "metin" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "gunluk_gorev_odulleri" (
  "user_id" BIGINT,
  "gun" TEXT,
  "odul" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "gun")
);
CREATE TABLE IF NOT EXISTS "gunluk_sandik" (
  "user_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "son_at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id")
);
CREATE TABLE IF NOT EXISTS "hatirlatmalar" (
  "anahtar" TEXT,
  "user_id" BIGINT NOT NULL,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("anahtar")
);
CREATE TABLE IF NOT EXISTS "hava_durumu" (
  "plaka" TEXT,
  "sicaklik" DOUBLE PRECISION,
  "yagis" DOUBLE PRECISION,
  "kod" BIGINT,
  "ruzgar" DOUBLE PRECISION,
  "gunduz" BIGINT,
  "guncellendi" BIGINT NOT NULL,
  "tahmin" TEXT,
  PRIMARY KEY ("plaka")
);
CREATE TABLE IF NOT EXISTS "hava_gecmisi" (
  "plaka" TEXT,
  "gun" TEXT,
  "olcum" BIGINT NOT NULL DEFAULT 0,
  "yagisli" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("plaka", "gun")
);
CREATE TABLE IF NOT EXISTS "hava_uyarilari" (
  "user_id" BIGINT NOT NULL,
  "plaka" TEXT NOT NULL,
  "tur" TEXT NOT NULL,
  "created_at" BIGINT NOT NULL
);
CREATE TABLE IF NOT EXISTS "hayvan_bakim" (
  "structure_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'AC',
  "beslendi_at" BIGINT,
  "hazir_at" BIGINT,
  PRIMARY KEY ("structure_id")
);
CREATE TABLE IF NOT EXISTS "hediyeler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "gonderen" BIGINT NOT NULL,
  "alici" BIGINT NOT NULL,
  "gun" TEXT NOT NULL,
  "icerik" TEXT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'BEKLIYOR',
  "at" BIGINT NOT NULL,
  "alindi_gun" TEXT,
  PRIMARY KEY ("id"),
  UNIQUE ("gonderen", "alici", "gun")
);
CREATE TABLE IF NOT EXISTS "ihale_haftalari" (
  "hafta" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "kuruldu_at" BIGINT NOT NULL,
  PRIMARY KEY ("hafta")
);
CREATE TABLE IF NOT EXISTS "ihale_teklifleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "ihale_id" BIGINT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "tutar" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'AKTIF',
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "ihaleler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "hafta" BIGINT NOT NULL,
  "parcel_id" TEXT NOT NULL,
  "set_kod" TEXT,
  "taban" BIGINT NOT NULL,
  "bitis" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'ACIK',
  "kazanan" BIGINT,
  "fiyat" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "il_talep" (
  "gun" TEXT,
  "plaka" TEXT,
  "urun" TEXT,
  "satilan" BIGINT NOT NULL,
  PRIMARY KEY ("gun", "plaka", "urun")
);
CREATE TABLE IF NOT EXISTS "ilce_mahalle_alanlari" (
  "ilce_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "yer_sayisi" BIGINT NOT NULL,
  "veri" TEXT NOT NULL,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("ilce_id")
);
CREATE TABLE IF NOT EXISTS "ilce_yer_taramasi" (
  "ilce_idx" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("ilce_idx")
);
CREATE TABLE IF NOT EXISTS "imar_karolari" (
  "kx" BIGINT,
  "ky" BIGINT,
  "surum" BIGINT NOT NULL,
  "kod" BYTEA NOT NULL,
  "ilce" BYTEA NOT NULL,
  "kaynak" TEXT NOT NULL,
  "created_at" TEXT NOT NULL,
  PRIMARY KEY ("kx", "ky")
);
CREATE TABLE IF NOT EXISTS "imece" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "hafta" BIGINT NOT NULL,
  "a_id" BIGINT NOT NULL,
  "b_id" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'DAVET',
  "puan_a" BIGINT NOT NULL DEFAULT 0,
  "puan_b" BIGINT NOT NULL DEFAULT 0,
  "created_at" BIGINT NOT NULL,
  "kabul_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "imece_gunluk" (
  "user_id" BIGINT,
  "gun" TEXT,
  "eylem" TEXT,
  "adet" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id", "gun", "eylem")
);
CREATE TABLE IF NOT EXISTS "imece_odul" (
  "imece_id" BIGINT,
  "user_id" BIGINT,
  "kademe" BIGINT,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("imece_id", "user_id", "kademe")
);
CREATE TABLE IF NOT EXISTS "inventory_ledger" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "item_id" TEXT NOT NULL,
  "delta" BIGINT NOT NULL,
  "reason" TEXT NOT NULL,
  "tx_group" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "isciler" (
  "user_id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "bitis" BIGINT NOT NULL,
  "son_tur" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id")
);
CREATE TABLE IF NOT EXISTS "isletmeler" (
  "kategori" TEXT,
  "ad" TEXT NOT NULL,
  "ikon" TEXT,
  "logo" TEXT,
  "renk" TEXT,
  "renk2" TEXT,
  "slogan" TEXT,
  "web" TEXT,
  "sponsor" BIGINT NOT NULL DEFAULT 0,
  "sozlesme_bas" BIGINT,
  "sozlesme_bit" BIGINT,
  "guncelleyen" BIGINT,
  "guncellendi" BIGINT,
  PRIMARY KEY ("kategori")
);
CREATE TABLE IF NOT EXISTS "kayit_taslaklari" (
  "token_ozet" TEXT,
  "saglayici" TEXT NOT NULL,
  "konu" TEXT,
  "email" TEXT NOT NULL,
  "email_dogrulandi" BIGINT NOT NULL DEFAULT 0,
  "ad_oneri" TEXT,
  "passkey" TEXT,
  "expires_at" BIGINT NOT NULL,
  PRIMARY KEY ("token_ozet")
);
CREATE TABLE IF NOT EXISTS "kimlik_baglantilari" (
  "saglayici" TEXT,
  "konu" TEXT,
  "user_id" BIGINT NOT NULL,
  "email" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("saglayici", "konu")
);
CREATE TABLE IF NOT EXISTS "kiralar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "sahip_id" BIGINT NOT NULL,
  "kiraci_id" BIGINT,
  "gunluk" BIGINT NOT NULL,
  "gun" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'TEKLIF',
  "created_at" BIGINT NOT NULL,
  "baslangic" BIGINT,
  "bitis" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "koleksiyon" (
  "user_id" BIGINT,
  "simge" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "simge")
);
CREATE TABLE IF NOT EXISTS "koleksiyon_odulleri" (
  "user_id" BIGINT,
  "kod" TEXT,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "kod")
);
CREATE TABLE IF NOT EXISTS "koop_yaris" (
  "hafta" BIGINT,
  "koop_id" BIGINT,
  "user_id" BIGINT,
  "puan" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("hafta", "koop_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "koop_yaris_gunluk" (
  "user_id" BIGINT,
  "gun" TEXT,
  "eylem" TEXT,
  "adet" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("user_id", "gun", "eylem")
);
CREATE TABLE IF NOT EXISTS "koop_yaris_hafta" (
  "hafta" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "sonuclandi_at" BIGINT NOT NULL,
  PRIMARY KEY ("hafta")
);
CREATE TABLE IF NOT EXISTS "koop_yaris_il" (
  "hafta" BIGINT,
  "il_id" BIGINT,
  "user_id" BIGINT,
  "puan" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("hafta", "il_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "koop_yaris_il_sonuc" (
  "hafta" BIGINT,
  "il_id" BIGINT,
  "sira" BIGINT NOT NULL,
  "puan" BIGINT NOT NULL,
  "oyuncu" BIGINT NOT NULL,
  "il_puani" DOUBLE PRECISION NOT NULL,
  "odul" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("hafta", "il_id")
);
CREATE TABLE IF NOT EXISTS "koop_yaris_sonuc" (
  "hafta" BIGINT,
  "koop_id" BIGINT,
  "sira" BIGINT,
  "puan" BIGINT NOT NULL,
  "sandik" BIGINT NOT NULL,
  "bonus" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("hafta", "koop_id")
);
CREATE TABLE IF NOT EXISTS "kooperatif_uyeleri" (
  "koop_id" BIGINT,
  "user_id" BIGINT,
  "katilim" BIGINT NOT NULL,
  PRIMARY KEY ("koop_id", "user_id")
);
CREATE TABLE IF NOT EXISTS "kooperatifler" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "il_id" BIGINT NOT NULL,
  "ad" TEXT NOT NULL,
  "aciklama" TEXT,
  "baskan_id" BIGINT NOT NULL,
  "created_at" BIGINT NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'AKTIF',
  PRIMARY KEY ("id"),
  UNIQUE ("il_id", "ad")
);
CREATE TABLE IF NOT EXISTS "koy_meydani" (
  "user_id" BIGINT,
  "kod" TEXT,
  "bitis" BIGINT NOT NULL,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "kod")
);
CREATE TABLE IF NOT EXISTS "kozmetikler" (
  "user_id" BIGINT,
  "kod" TEXT,
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("user_id", "kod")
);
CREATE TABLE IF NOT EXISTS "listings" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "seller_id" BIGINT NOT NULL,
  "asking_price" BIGINT NOT NULL,
  "listing_currency" TEXT NOT NULL DEFAULT 'AKCE',
  "asset_snapshot" TEXT NOT NULL,
  "fee_rate" DOUBLE PRECISION NOT NULL,
  "buyer_condition" TEXT NOT NULL DEFAULT 'HERKES',
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "created_at" BIGINT NOT NULL,
  "expires_at" BIGINT NOT NULL,
  "closed_at" BIGINT,
  "version" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "moderasyon_islemleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "tur" TEXT NOT NULL,
  "hedef" TEXT NOT NULL,
  "gerekce" TEXT NOT NULL,
  "sikayet_id" BIGINT,
  "durum" TEXT NOT NULL DEFAULT 'ONAY_BEKLIYOR',
  "oneren_id" BIGINT NOT NULL,
  "onaylayan_id" BIGINT,
  "created_at" BIGINT NOT NULL,
  "karar_at" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "notifications" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "text" TEXT NOT NULL,
  "link" TEXT,
  "read_at" TEXT,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "npc_demand" (
  "day" TEXT,
  "item_id" TEXT,
  "sold" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("day", "item_id")
);
CREATE TABLE IF NOT EXISTS "npc_kisisel" (
  "day" TEXT,
  "user_id" BIGINT,
  "item_id" TEXT,
  "sold" BIGINT NOT NULL DEFAULT 0,
  PRIMARY KEY ("day", "user_id", "item_id")
);
CREATE TABLE IF NOT EXISTS "oauth_durumlari" (
  "state_ozet" TEXT,
  "saglayici" TEXT NOT NULL,
  "nonce" TEXT NOT NULL,
  "dogrulayici" TEXT,
  "tarayici_ozet" TEXT NOT NULL,
  "mod" TEXT NOT NULL,
  "user_id" BIGINT,
  "expires_at" BIGINT NOT NULL,
  PRIMARY KEY ("state_ozet")
);
CREATE TABLE IF NOT EXISTS "ortaklar" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "sahip_id" BIGINT NOT NULL,
  "ortak_id" BIGINT NOT NULL,
  "pay" DOUBLE PRECISION NOT NULL,
  "durum" TEXT NOT NULL DEFAULT 'DAVET',
  "created_at" BIGINT NOT NULL,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "parcel_ownership" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "start_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  "end_at" TEXT,
  "reason" TEXT NOT NULL,
  "price" NUMERIC(14,2),
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "parcels" (
  "id" TEXT,
  "region_id" BIGINT NOT NULL,
  "ilce_id" BIGINT NOT NULL,
  "il_id" BIGINT NOT NULL,
  "district_code" TEXT NOT NULL,
  "area_m2" BIGINT NOT NULL,
  "zoning_type" TEXT NOT NULL,
  "zoning_source" TEXT NOT NULL,
  "centroid_lon" DOUBLE PRECISION NOT NULL,
  "centroid_lat" DOUBLE PRECISION NOT NULL,
  "grid_x" BIGINT NOT NULL,
  "grid_y" BIGINT NOT NULL,
  "owner_user_id" BIGINT,
  "status" TEXT NOT NULL DEFAULT 'ACTIVE',
  "geom_version" TEXT NOT NULL DEFAULT 'z20-v1',
  "version" BIGINT NOT NULL DEFAULT 0,
  "acquired_at" TEXT,
  "birlesik_id" TEXT,
  "uye_sayisi" BIGINT NOT NULL DEFAULT 0,
  "konum_kati" DOUBLE PRECISION,
  "konum_surum" BIGINT,
  "konum_json" TEXT,
  PRIMARY KEY ("id"),
  "geom" geometry(Polygon, 4326),
  "merkez" geometry(Point, 4326)
);
CREATE TABLE IF NOT EXISTS "parsel_susleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parcel_id" TEXT NOT NULL,
  "user_id" BIGINT NOT NULL,
  "tur" TEXT NOT NULL,
  "yuva" BIGINT NOT NULL,
  "at" BIGINT NOT NULL,
  PRIMARY KEY ("id"),
  UNIQUE ("parcel_id", "yuva")
);
CREATE TABLE IF NOT EXISTS "passkeyler" (
  "id" TEXT,
  "user_id" BIGINT NOT NULL,
  "acik_anahtar" BYTEA NOT NULL,
  "sayac" BIGINT NOT NULL DEFAULT 0,
  "tasima" TEXT,
  "ad" TEXT,
  "created_at" BIGINT NOT NULL,
  "son_kullanim" BIGINT,
  PRIMARY KEY ("id")
);
CREATE TABLE IF NOT EXISTS "push_abonelikleri" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "user_id" BIGINT NOT NULL,
  "endpoint" TEXT NOT NULL,
  "p256dh" TEXT NOT NULL,
  "auth" TEXT NOT NULL,
  "created_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("id"),
  UNIQUE ("endpoint")
);
CREATE TABLE IF NOT EXISTS "quest_progress" (
  "user_id" BIGINT,
  "quest_code" TEXT,
  "completed_at" TEXT NOT NULL DEFAULT to_char(now() AT TIME ZONE 'UTC', 'YYYY-MM-DD HH24:MI:SS'),
  PRIMARY KEY ("user_id", "quest_code")
);
CREATE TABLE IF NOT EXISTS "regions" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
  "parent_id" BIGINT,
  "type" TEXT NOT NULL,
  "code" TEXT NOT NULL,
  "name" TEXT NOT NULL,
  "plaka" TEXT,
  "center_lon" DOUBLE PRECISION,
  "center_lat" DOUBLE PRECISION,
  "bbox" TEXT,
  "place_class" TEXT,
  "source_idx" BIGINT,
  "attractiveness" DOUBLE PRECISION NOT NULL DEFAULT 1.0,
